CREATE TABLE public.people (small_value smallint NOT NULL, id integer NOT NULL, big_value bigint NOT NULL, real_value real NOT NULL, double_value double precision NOT NULL, name text NOT NULL, note varchar, fixed_value char(3) NOT NULL, active boolean NOT NULL, data bytea NOT NULL, amount numeric NOT NULL, day date NOT NULL, clock time NOT NULL, local_time timestamp NOT NULL, instant timestamptz NOT NULL, duration interval NOT NULL, document json NOT NULL, binary_document jsonb NOT NULL, external_id uuid NOT NULL);
CREATE TABLE public.ppx_items (tenant integer NOT NULL DEFAULT 1, id integer GENERATED BY DEFAULT AS IDENTITY, name text NOT NULL DEFAULT 'unnamed' UNIQUE, note text, document json NOT NULL DEFAULT '{}', revision integer NOT NULL DEFAULT 0, PRIMARY KEY (tenant, id));
CREATE TYPE public.mood AS ENUM ('happy', 'sad');
CREATE DOMAIN public.small_native AS int2;
CREATE DOMAIN public.nested_native AS public.small_native;
CREATE DOMAIN public.required_native AS text NOT NULL;
CREATE DOMAIN public.intarray_native AS int4[];
CREATE TABLE public.native_items (id int4 NOT NULL DEFAULT 42, mood public.mood NOT NULL DEFAULT 'happy', small_value public.small_native NOT NULL DEFAULT 7, nested_value public.nested_native NOT NULL DEFAULT 8, required_value public.required_native DEFAULT 'required', numbers int4[] NOT NULL DEFAULT '{}', nullable_numbers int4[], moods public.mood[] NOT NULL DEFAULT '{}', domain_numbers public.nested_native[] NOT NULL DEFAULT '{}', domain_array public.intarray_native NOT NULL DEFAULT '{}', array_bool pg_catalog.bool[] NOT NULL DEFAULT '{}', array_int2 pg_catalog.int2[] NOT NULL DEFAULT '{}', array_int4 pg_catalog.int4[] NOT NULL DEFAULT '{}', array_int8 pg_catalog.int8[] NOT NULL DEFAULT '{}', array_float4 pg_catalog.float4[] NOT NULL DEFAULT '{}', array_float8 pg_catalog.float8[] NOT NULL DEFAULT '{}', array_text pg_catalog.text[] NOT NULL DEFAULT '{}', array_varchar pg_catalog.varchar[] NOT NULL DEFAULT '{}', array_bpchar pg_catalog.bpchar[] NOT NULL DEFAULT '{}', array_bytea pg_catalog.bytea[] NOT NULL DEFAULT '{}', array_numeric pg_catalog.numeric[] NOT NULL DEFAULT '{}', array_date pg_catalog.date[] NOT NULL DEFAULT '{}', array_time pg_catalog.time[] NOT NULL DEFAULT '{}', array_timestamp pg_catalog.timestamp[] NOT NULL DEFAULT '{}', array_timestamptz pg_catalog.timestamptz[] NOT NULL DEFAULT '{}', array_interval pg_catalog.interval[] NOT NULL DEFAULT '{}', array_json pg_catalog.json[] NOT NULL DEFAULT '{}', array_jsonb pg_catalog.jsonb[] NOT NULL DEFAULT '{}', array_uuid pg_catalog.uuid[] NOT NULL DEFAULT '{}', instant pg_catalog.timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE join_people (id integer NOT NULL, name text NOT NULL, note text);
CREATE TABLE join_links (id integer NOT NULL, person_id integer NOT NULL, label text, active boolean NOT NULL);
CREATE TABLE public.ppx_mixed_items (id bigint PRIMARY KEY, name text NOT NULL, note text);
CREATE TABLE typmod_values(id integer PRIMARY KEY,v varchar(10) NOT NULL,c char(3) NOT NULL,n numeric(8,2) NOT NULL,t timestamp(3) NOT NULL,z timestamptz(3) NOT NULL,tm time(3) NOT NULL,i interval day to second(3) NOT NULL,vs varchar(10)[] NOT NULL);
CREATE TABLE group_keys(tenant integer NOT NULL,id integer NOT NULL,name text NOT NULL,PRIMARY KEY(tenant,id));
CREATE TABLE deferrable_group_keys(tenant integer NOT NULL,id integer NOT NULL,name text NOT NULL,PRIMARY KEY(tenant,id) DEFERRABLE INITIALLY IMMEDIATE);
CREATE TABLE public.quoted ("odd""name" text NOT NULL, method text NOT NULL);
